package ru.mirea.aquarium.backend.team.Seregin.service;
import jakarta.persistence.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import ru.mirea.aquarium.backend.team.Seregin.domain.*;import ru.mirea.aquarium.backend.team.Seregin.dto.ServiceRequestDto;import ru.mirea.aquarium.backend.team.Seregin.repository.ServiceRequestRepository;import java.util.*;
@Service public class ServiceRequestService{
 private static final Set<String>SORT=Set.of("createdAt","updatedAt","scheduledAt","priority","price","status");private final ServiceRequestRepository repo;public ServiceRequestService(ServiceRequestRepository r){repo=r;}
 @Transactional(readOnly=true)public Page<ServiceRequest>list(String q,UUID clientId,RequestStatus status,Boolean archived,int page,int size,String sort,String direction){if(page<0||size<1||size>100)throw new IllegalArgumentException("Размер страницы должен быть от 1 до 100");if(!SORT.contains(sort))throw new IllegalArgumentException("Недопустимое поле сортировки");Specification<ServiceRequest>s=(r,x,c)->c.conjunction();if(q!=null&&!q.isBlank()){String p="%"+q.trim().toLowerCase(Locale.ROOT)+"%";s=s.and((r,x,c)->c.or(c.like(c.lower(r.get("code")),p),c.like(c.lower(r.get("description")),p)));}if(clientId!=null)s=s.and((r,x,c)->c.equal(r.get("clientId"),clientId));if(status!=null)s=s.and((r,x,c)->c.equal(r.get("status"),status));if(archived!=null)s=s.and((r,x,c)->c.equal(r.get("archived"),archived));Sort.Direction d="asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC;return repo.findAll(s,PageRequest.of(page,size,Sort.by(d,sort)));}
 @Transactional(readOnly=true)public ServiceRequest get(UUID id){return repo.findById(id).orElseThrow(()->new EntityNotFoundException("Заявка не найдена"));}
 @Transactional public ServiceRequest create(ServiceRequestDto d){ServiceRequest r=new ServiceRequest();apply(r,d);return repo.save(r);}
 @Transactional public ServiceRequest update(UUID id,ServiceRequestDto d){ServiceRequest r=get(id);if(d.version()==null||d.version()!=r.getVersion())throw new OptimisticLockException("Заявка уже изменена другим пользователем");apply(r,d);return repo.save(r);}
 @Transactional public void archive(UUID id){get(id).setArchived(true);}@Transactional public ServiceRequest restore(UUID id){ServiceRequest r=get(id);r.setArchived(false);return r;}
 private void apply(ServiceRequest r,ServiceRequestDto d){r.setCode(d.code().trim());r.setClientId(d.clientId());r.setAquariumId(d.aquariumId());r.setAquariumType(d.aquariumType());r.setServiceType(d.serviceType());r.setDescription(d.description().trim());r.setStatus(d.status());r.setPriority(d.priority());r.setScheduledAt(d.scheduledAt());r.setPrice(d.price());}
}
